/**
 * Types from the API contract, for services to type their calls with.
 *
 * `./openapi.d.ts` is generated by openapi-typescript from the vendored
 * contract (`test/contract/openapi.json`, 0.34.0): run
 * `npm run gen:api-types` after `npm run contract:vendor`, never edit it by
 * hand (scripts/ci.sh fails when it is stale). These helpers read it:
 *
 *   type Profile = ApiSchema<'Profile'>;
 *   const profile = await apiGet<ApiData<'/profile', 'get'>>('/profile');
 *   const body: ApiBody<'/profile/locale', 'post'> = { locale: 'is' };
 *
 * The contract's success schemas describe the INSIDE of the `{ ok, data }`
 * envelope, which the client unwraps, so `ApiData` is what `apiGet` returns.
 * A type is a promise about the wire, not a check: decode what a screen
 * relies on (`options.decode`), fail-soft where iOS is fail-soft.
 */
import type { components, paths } from './openapi';

export type ApiSchemas = components['schemas'];
export type ApiSchemaName = keyof ApiSchemas;
/** A named schema (`#/components/schemas/<Name>`). */
export type ApiSchema<Name extends ApiSchemaName> = ApiSchemas[Name];

export type ApiPath = keyof paths;
export type ApiMethod = 'get' | 'post' | 'put' | 'patch' | 'delete';

/** The methods a path declares. */
export type ApiMethodsOf<P extends ApiPath> = {
  [M in ApiMethod]: paths[P][M] extends undefined | never ? never : M;
}[ApiMethod];

/** One operation of the contract. */
export type ApiOperation<P extends ApiPath, M extends ApiMethodsOf<P>> = NonNullable<paths[P][M]>;

type SuccessStatus = 200 | 201 | 202;

type JsonContent<R> = R extends { content: { 'application/json': infer Body } } ? Body : never;

type Responses<P extends ApiPath, M extends ApiMethodsOf<P>> =
  ApiOperation<P, M> extends { responses: infer R } ? R : never;

/** The `data` of a 2xx answer, as the client returns it. */
export type ApiData<P extends ApiPath, M extends ApiMethodsOf<P>> = JsonContent<
  Responses<P, M>[Extract<keyof Responses<P, M>, SuccessStatus>]
>;

/** The JSON request body. */
export type ApiBody<P extends ApiPath, M extends ApiMethodsOf<P>> =
  ApiOperation<P, M> extends { requestBody?: infer B } ? JsonContent<NonNullable<B>> : never;

/** The query parameters. */
export type ApiQuery<P extends ApiPath, M extends ApiMethodsOf<P>> =
  ApiOperation<P, M> extends { parameters: { query?: infer Q } } ? NonNullable<Q> : never;

/** The path parameters (`{ venueId }` for `/venues/{venueId}`). */
export type ApiPathParams<P extends ApiPath, M extends ApiMethodsOf<P>> =
  ApiOperation<P, M> extends { parameters: { path?: infer V } } ? NonNullable<V> : never;

/** The base problem body every refusal shares. */
export type ApiProblem = ApiSchema<'Problem'>;
